<div class="card"><h1>Edit Listing</h1><?php if($message): ?><div class="alert"><?= e($message) ?></div><?php endif; ?><form method="post"><label>Title</label><input name="title" value="<?= e($listing['title']) ?>"><label>Description</label><textarea name="description"><?= e($listing['description']) ?></textarea><label>Category</label><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><label>Condition</label><select name="condition"><option value="good">Good</option><option value="new">New</option><option value="like_new">Like New</option><option value="fair">Fair</option></select><label>Starting Price</label><input type="number" step="0.01" name="starting_price" value="<?= e($listing['starting_price']) ?>"><label>Reserve Price</label><input type="number" step="0.01" name="reserve_price" value="<?= e($listing['reserve_price']) ?>"><label>End</label><input type="datetime-local" name="end_datetime" value="<?= date('Y-m-d\\TH:i', strtotime($listing['end_datetime'])) ?>"><button>Save if zero bids</button></form></div>
